import React from 'react'
import ReactDOM from 'react-dom'
import { I18n } from 'react-i18nify-lite'
import { HashRouter, Route, Switch } from 'react-router-dom'
import posed, { PoseGroup } from 'react-pose'
import {ThemeProvider, createGlobalStyle} from 'styled-components'
import { IconStyle, FormStyle } from 'prey-stash'

import {
  Segundo,
  dark,
  ButtonStyle,
  FeedbackStyle
} from './assets/stash'

import OnBoardingStyles, { obScreenCSS } from './onboarding/onboardingstyles';

import { initLang } from './i18n/base';

import './assets/typography/style.css';

// Build-time check so each bundle only contains its own platform's screens.
const { paths, platformStyles } =
  process.env.REACT_APP_ONBOARDING_TYPE === 'ios'
    ? require('./routes/ios')
    : require('./routes/android');

const GlobalStyle = createGlobalStyle`
  ${Segundo(dark)}
  ${ButtonStyle(dark)}
  ${FeedbackStyle(dark)}
  ${FormStyle(dark)}
  ${IconStyle(dark)}
  ${OnBoardingStyles(dark)}
  ${obScreenCSS(dark)}
  ${platformStyles}
`

const RouteContainer = posed.div({
  init: {
    opacity: 0,
  },
  enter: {
    opacity: 1,
    beforeChildren: true,
    staggerChildren: 50,
  },
  exit: {
    opacity: 0,
    staggerChildren: 20,
    staggerDirection: -1,
  },
});

class App extends React.Component {
  constructor(props) {
    super(props);
    this.state = {}
  }
  componentWillMount() {
    initLang();
  }
  renderer = () => (
    <Route
      render={
        ({ location, match }) => (
          <PoseGroup>
            <RouteContainer key={location.pathname}>
              <Switch location={location}>
                {
                  paths.map((item, key)=>{
                    let setLang = location.pathname.match(/\/(es|en)\//)
                    let path = item.url
                    let lang
                    if(setLang && setLang.length > 0 ){
                      lang = `/${setLang[1]}`
                      I18n.setLocale(setLang[1])
                    } else {
                      lang = ''
                      I18n.setLocale('en')
                    }
                    path = `${lang}${item.url}`
                    return <Route exact path={path} component={item.component} key={key} />
                  })
                }
              </Switch>
            </RouteContainer>
          </PoseGroup>
      )}
    />
  );
  render() {
    return (
      <React.Fragment>
        <GlobalStyle />
        <ThemeProvider theme={dark}>
          {this.renderer()}
        </ThemeProvider>
      </React.Fragment>
    )
  }
}

ReactDOM.render(
  <HashRouter>
    <App />
  </HashRouter>,
  document.getElementById('root')
);
